async function acceptScore(data){
  songbookId=data.songId;
  if(data.kind==='scan'){
    pendingScanLink=data.songId;pendingScanTitle=data.title;songbookId=null;
    $('scanDialog').showModal();
    await importScanFile(new File([data.pdf],data.title+'.pdf',{type:'application/pdf'}));
    sourceCanvas.dataset.title=data.title;
    return;
  }
  const saved=data.session;
  if(saved?.version===1){
    const doc=M.parse(saved.sourceXml);
    if(!M.parts(doc).some(p=>p.id===saved.partId))throw Error('The saved melody part is missing. Import the MusicXML instead.');
    await load(doc,saved.currentFile||data.title,!!saved.isDraft);
    partId=saved.partId;editPartId=partId;
    for(const [key,value]of Object.entries(saved.options||{})){
      if(key==='chords'){options.chords=value===true;$('chordToggle').checked=options.chords;continue;}
      const control=$(key==='semitones'?'transpose':key);
      if(!Object.hasOwn(options,key)||!control||control.tagName!=='SELECT')continue;
      if(![...control.options].some(o=>o.value===String(value)))continue;
      options[key]=['octave','semitones'].includes(key)?Number(value):value;control.value=value;
    }
    chordOverrides=saved.chordOverrides||{};generatedEdits=saved.generatedEdits||{};
    if(Number.isFinite(saved.tempo)&&saved.tempo>=30&&saved.tempo<=240)$('tempo').value=saved.tempo;
    syncPart();await refresh();
  }else{
    // A plain MusicXML import starts without newly generated accompaniment.
    for(const key of ['harmony','fiddleHarmony','drone']){options[key]='off';$(key).value='off';}
    options.chords=false;$('chordToggle').checked=false;
    await load(M.parse(data.xml),data.title);
  }
}
